private <V, E> boolean isCompleteBipartite(Graph<V, E> graph) {
    // Check if the graph is bipartite
    boolean isBipartite = true;
    Set<V> visited = new HashSet<>();
    Map<V, Integer> color = new HashMap<>();

    for (V v : graph.getVertices()) {
        if (!visited.contains(v)) {
            if (!bfsCheck(graph, v, visited, color)) {
                isBipartite = false;
                break;
            }
        }
    }

    if (!isBipartite) {
        return false;
    }

    // Check if all edges are between the two sets of vertices
    for (V v : graph.getVertices()) {
        for (V neighbor : graph.getAdjacencyList().get(v)) {
            if (color.get(v).equals(color.get(neighbor))) {
                return false;
            }
        }
    }

    return true;
}

private <V, E> boolean bfsCheck(Graph<V, E> graph, V v, Set<V> visited, Map<V, Integer> color) {
    Queue<V> queue = new LinkedList<>();
    queue.add(v);
    visited.add(v);
    color.put(v, 0);

    while (!queue.isEmpty()) {
        V u = queue.poll();

        for (V neighbor : graph.getAdjacencyList().get(u)) {
            if (!visited.contains(neighbor)) {
                queue.add(neighbor);
                visited.add(neighbor);
                color.put(neighbor, 1 - color.get(u));
            } else if (color.get(neighbor).equals(color.get(u))) {
                return false;
            }
        }
    }

    return true;
}

