    double x = box.getMinX();

    if (width <= 0) {
        throw new IllegalArgumentException("Box width must be greater than zero");
    }

    double halfWidth = width / 2;
    double x1 = x;
    double x2 = x + halfWidth;

    Box2D box1 = new Box2D(x1, box.getMinY(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(x2, box.getMinY(), halfWidth, box.getHeight());

    return Pair.with(box1, box2);
}

