    if (b1 == -1) {
        return 0;
    }
    int b2 = readRawByte();
    if (b2 == -1) {
        throw new IOException("Unexpected EOF");
    }
    return ((b1 & 0x7f) << 7) | (b2 & 0x7f);
}

int function() throws IOException {
    int tag = readRawVarint();
    return tag == 0 ? 0 : tag >>> 3;
}

private int readRawVarint() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        byte b = readRawByte();
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Protocol message contained a varint which is too big.");
}

